const BillingSection = ({ projects = [], invoices = [], budget = null }) => {
  const [payInvoice, setPayInvoice] = useState(null)
  const [payPhone, setPayPhone] = useState('')
  const [payStage, setPayStage] = useState('idle') // idle | sending | waiting | completed | failed
  const [payMsg, setPayMsg] = useState('')

  const startSTKPush = async () => {
    if (!payInvoice) return
    const clean = String(payPhone).replace(/\D/g, '')
    const msisdn = clean.startsWith('0') ? '254' + clean.slice(1) : clean
    if (msisdn.length < 12) { toast('Enter a valid Safaricom number, e.g. 0712 345 678', 'error'); return }
    setPayStage('sending'); setPayMsg('')
    try {
      const res = await fetch(getApiUrl('/api/mpesa/stkpush'), {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          phoneNumber: msisdn,
          amount: payInvoice.amount,
          accountReference: payInvoice.invoiceNumber || ('INV-' + payInvoice.id),
          description: 'Invoice payment - The Greggory Systems & Strategy Firm',
        }),
      })
      const data = await res.json()
      if (!data.success) { setPayStage('failed'); setPayMsg(data.error || data.message || 'Could not initiate the payment prompt.'); return }
      if (data.simulated) { setPayStage('failed'); setPayMsg('Live M-Pesa prompts are not enabled yet. Please pay via Send Money below - your reference is ' + (payInvoice.invoiceNumber || payInvoice.id) + '.'); return }
      setPayStage('waiting'); setPayMsg('Check your phone - an M-Pesa prompt has been sent. Enter your PIN to approve the payment.')
      let tries = 0
      const poll = setInterval(async () => {
        tries++
        try {
          const sres = await fetch(getApiUrl('/api/mpesa/status/' + data.checkoutRequestId))
          const sdata = await sres.json()
          if (sdata.success && sdata.status === 'completed') { clearInterval(poll); setPayStage('completed'); setPayMsg('Payment received. Thank you!' + (sdata.mpesa_receipt ? ' Receipt: ' + sdata.mpesa_receipt : '')); return }
          if (sdata.success && sdata.status === 'failed') { clearInterval(poll); setPayStage('failed'); setPayMsg(sdata.result_desc || 'The payment was cancelled or failed.'); return }
        } catch (e) {}
        if (tries > 40) { clearInterval(poll); setPayStage('failed'); setPayMsg('Timed out waiting for confirmation. If you entered your PIN, the payment will reflect shortly.') }
      }, 3000)
    } catch (e) {
      setPayStage('failed'); setPayMsg('Network error while contacting M-Pesa. You can still pay via Send Money below.')
    }
  }

  const closePayModal = () => {
    if (payStage === 'sending' || payStage === 'waiting') return
    setPayInvoice(null); setPayStage('idle'); setPayMsg('')
  }
  const totalBudget = budget?.planned || 0
  const totalSpent = budget?.spent || 0
  const remaining = totalBudget - totalSpent
  const utilPct = budget?.planned > 0 ? Math.round((totalSpent / totalBudget) * 100) : 0

  return (
    <div className="space-y-10">
      <SectionHeader title="Billing Ledger" subtitle="Capital allocation and burn matrix telemetry" />

      {projects.length === 0 ? (
        <div className="text-center py-20 border-2 border-dashed border-white/5 rounded-[40px]">
           <DollarSign className="w-12 h-12 text-slate-800 mx-auto mb-4" />
           <p className="text-[10px] font-black text-slate-600 uppercase tracking-widest">Zero Billing Frequencies</p>
        </div>
      ) : (
        <>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
            <KpiCard icon={DollarSign} label="Total Budget" value={formatKSH(totalBudget)} color="bg-gold-500/10 text-gold-500 border-gold-500/20" />
            <KpiCard icon={TrendingUp} label="Spent to Date" value={formatKSH(totalSpent)} delta={utilPct} deltaLabel="Utilization" color="bg-sky-500/10 text-sky-400 border-sky-500/20" />
            <KpiCard icon={CheckCircle} label="Remaining Budget" value={formatKSH(remaining)} color="bg-emerald-500/10 text-emerald-400 border-emerald-500/20" />
            <KpiCard icon={AlertCircle} label="Risk Exposure" value={formatKSH(0)} color="bg-rose-500/10 text-rose-500 border-rose-500/20" />
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            <SectionCard className="p-10 border border-white/10">
              <h3 className="text-[10px] font-black text-white uppercase tracking-[0.3em] mb-10">Entity Allocation Tracker</h3>
              <div className="space-y-8">
                {projects.map(p => (
                  <div key={p.id}>
                    <div className="flex justify-between mb-4">
                       <span className="text-sm font-black text-white uppercase">{p.name}</span>
                       <span className="text-xs font-black text-slate-300">{formatKSH(p.actualBudget)} / {formatKSH(p.plannedBudget)}</span>
                    </div>
                    <GradientBar value={p.actualBudget} max={p.plannedBudget} />
                  </div>
                ))}
              </div>
            </SectionCard>

            <SectionCard className="p-8 border border-white/10 overflow-hidden">
              <h3 className="text-[10px] font-black text-white uppercase tracking-[0.3em] mb-8">Invoices</h3>
              <div className="overflow-x-auto">
                <table className="w-full text-left">
                  <thead>
                    <tr className="border-b border-white/5">
                      <th className="pb-4 text-[9px] font-black text-slate-500 uppercase tracking-widest">Invoice</th>
                      <th className="pb-4 text-[9px] font-black text-slate-500 uppercase tracking-widest text-right">Amount</th>
                      <th className="pb-4 text-[9px] font-black text-slate-500 uppercase tracking-widest">Status</th>
                      <th className="pb-4 text-[9px] font-black text-slate-500 uppercase tracking-widest text-right">Actions</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-white/5">
                    {invoices.map(inv => (
                      <tr key={inv.id}>
                        <td className="py-4 text-xs font-black text-gold-500 font-mono">{inv.invoiceNumber || inv.id}</td>
                        <td className="py-4 text-xs font-black text-white text-right">{formatKSH(inv.amount)}</td>
                        <td className="py-4"><StatusBadge status={inv.status} /></td>
                        <td className="py-4">
                          <div className="flex items-center justify-end gap-2">
                            {inv.status !== 'paid' && (
                              <button onClick={() => { setPayInvoice(inv); setPayPhone(''); setPayStage('idle'); setPayMsg('') }} className="px-3 py-1.5 rounded-lg bg-teal-500/10 border border-teal-500/30 text-teal-400 text-[9px] font-black uppercase tracking-widest hover:bg-teal-500 hover:text-white transition-all">Pay Now</button>
                            )}
                            <a href={getApiUrl('/api/documents/invoices/' + inv.id + '/pdf')} title="Download PDF" className="p-2 rounded-lg bg-white/5 text-slate-300 hover:text-teal-400 hover:bg-white/10 transition-all"><Download size={13} /></a>
                          </div>
                        </td>
                      </tr>
                    ))}
                    {invoices.length === 0 && <tr><td colSpan="4" className="py-8 text-center text-[9px] font-black text-slate-600 uppercase tracking-widest">No invoices yet</td></tr>}
                  </tbody>
                </table>
              </div>
            </SectionCard>
          </div>
        </>
      )}

      {payInvoice && (
        <Modal open={true} onClose={closePayModal} title="Pay Invoice">
          <div className="space-y-5">
            <div className="flex justify-between items-center bg-white/5 rounded-xl p-4 border border-white/10">
               <div>
                  <p className="text-[9px] font-black text-slate-500 uppercase tracking-widest">Invoice</p>
                  <p className="text-xs font-black text-gold-500 font-mono">{payInvoice.invoiceNumber || payInvoice.id}</p>
               </div>
               <p className="text-xl font-black text-white">{formatKSH(payInvoice.amount)}</p>
            </div>
            {payStage === 'idle' || payStage === 'failed' ? (
              <>
                <div>
                  <label className="block text-[9px] font-black text-slate-400 uppercase tracking-widest mb-2">Your M-Pesa phone number</label>
                  <input value={payPhone} onChange={e => setPayPhone(e.target.value)} placeholder="0712 345 678" inputMode="tel" className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-sm font-bold text-white placeholder-slate-600 focus:outline-none focus:border-teal-500" />
                  <button onClick={startSTKPush} disabled={payStage === 'sending'} className="mt-3 w-full py-3 rounded-xl bg-teal-600 text-white text-[10px] font-black uppercase tracking-[0.2em] hover:bg-teal-500 transition-all disabled:opacity-50">
                    {payStage === 'sending' ? 'Sending prompt...' : 'Pay via M-Pesa Prompt'}
                  </button>
                  <p className="mt-2 text-[9px] text-slate-500 font-bold">You will receive a prompt on your phone. Enter your M-Pesa PIN to approve.</p>
                </div>
                {payStage === 'failed' && payMsg && <p className="text-[10px] font-black text-rose-400">{payMsg}</p>}
                <div className="border-t border-white/10 pt-4">
                   <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-2">Or pay manually via Send Money</p>
                   <ol className="text-[10px] text-slate-300 font-semibold space-y-1 list-decimal list-inside">
                      <li>M-Pesa menu, choose Send Money</li>
                      <li>Send to <span className="font-black text-teal-400">+254 715 312 251</span></li>
                      <li>Reference: <span className="font-black text-teal-400">{payInvoice.invoiceNumber || payInvoice.id}</span></li>
                   </ol>
                </div>
              </>
            ) : payStage === 'waiting' ? (
              <div className="text-center py-6">
                 <RefreshCw size={28} className="animate-spin text-teal-400 mx-auto mb-4" />
                 <p className="text-xs font-black text-white uppercase tracking-widest">Awaiting M-Pesa Confirmation</p>
                 <p className="mt-3 text-[11px] text-slate-400 font-semibold max-w-xs mx-auto">{payMsg}</p>
              </div>
            ) : payStage === 'sending' ? (
              <div className="text-center py-6"><RefreshCw size={24} className="animate-spin text-teal-400 mx-auto" /><p className="mt-3 text-[10px] font-black text-slate-400 uppercase tracking-widest">Initiating payment...</p></div>
            ) : (
              <div className="text-center py-6">
                 <CheckCircle size={40} className="text-emerald-400 mx-auto mb-3" />
                 <p className="text-sm font-black text-emerald-400 uppercase tracking-widest">Payment Complete</p>
                 {payMsg && <p className="mt-2 text-[10px] text-slate-400 font-semibold">{payMsg}</p>}
              </div>
            )}
          </div>
        </Modal>
      )}
    </div>
  )
}

