const FeedbackSection = ({ user }) => {
  const [rating, setRating] = useState(0)
  const [hoverRating, setHoverRating] = useState(0)
  const [incidentMsg, setIncidentMsg] = useState('')
  const [isSubmitting, setIsSubmitting] = useState(false)

  const submitSatisfaction = async () => {
    if (rating === 0) {
      toast('Select a satisfaction level', 'warn')
      return
    }
    setIsSubmitting(true)
    try {
      const response = await fetch(getApiUrl('/api/feedback'), {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${user?.token}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          feedback_type: 'satisfaction',
          rating: rating,
          message: `Client satisfaction rating: ${rating}/5`,
          title: 'Satisfaction Relay'
        })
      })
      const data = await response.json()
      if (data.success) {
        toast('Satisfaction relay synchronized', 'success')
        setRating(0)
      }
    } catch (err) {
      toast('Relay failure', 'error')
    } finally {
      setIsSubmitting(false)
    }
  }

  const submitIncident = async () => {
    if (!incidentMsg.trim()) {
      toast('Enter incident details', 'warn')
      return
    }
    setIsSubmitting(true)
    try {
      const response = await fetch(getApiUrl('/api/feedback'), {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${user?.token}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          feedback_type: 'incident',
          message: incidentMsg,
          title: 'Tactical Incident Report',
          priority: 'High'
        })
      })
      const data = await response.json()
      if (data.success) {
        toast('Incident alert initialized', 'success')
        setIncidentMsg('')
      }
    } catch (err) {
      toast('Alert transmission failure', 'error')
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <div className="space-y-10">
      <SectionHeader title="Feedback & Support" subtitle="Direct operational reports and feature requests" />
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <SectionCard className="p-8">
          <h3 className="font-black text-white uppercase text-sm mb-6 flex items-center gap-3"><Star className="w-5 h-5 text-gold-500" />Satisfaction Relay</h3>
          <p className="text-xs font-medium text-slate-500 uppercase tracking-[0.2em] mb-8">Synchronize your experience rating with the firm command.</p>
          <div className="flex gap-4 mb-8">
            {[1, 2, 3, 4, 5].map(s => (
              <button
                key={s}
                onMouseEnter={() => setHoverRating(s)}
                onMouseLeave={() => setHoverRating(0)}
                onClick={() => setRating(s)}
                className="hover:scale-110 transition-transform focus:outline-none"
              >
                <Star
                  className={`w-10 h-10 transition-colors ${
                    (hoverRating || rating) >= s ? 'text-gold-500 fill-gold-500' : 'text-slate-800'
                  }`}
                />
              </button>
            ))}
          </div>
          <button
            onClick={submitSatisfaction}
            disabled={isSubmitting}
            className="w-full bg-gold-500 text-slate-950 py-4 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-gold-400 transition-all disabled:opacity-50"
          >
            {isSubmitting ? 'Synchronizing...' : 'Execute Submission'}
          </button>
        </SectionCard>

        <SectionCard className="p-8">
          <h3 className="font-black text-white uppercase text-sm mb-6 flex items-center gap-3"><AlertTriangle className="w-5 h-5 text-rose-500" />Incident Report</h3>
          <p className="text-xs font-medium text-slate-500 uppercase tracking-[0.2em] mb-4">Report tactical disruptions or system anomalies.</p>
          <textarea
            value={incidentMsg}
            onChange={(e) => setIncidentMsg(e.target.value)}
            placeholder="Describe the anomaly..."
            className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-sm text-white placeholder-slate-600 focus:outline-none focus:ring-1 focus:ring-rose-500/50 mb-6 h-24 resize-none"
          />
          <button
            onClick={submitIncident}
            disabled={isSubmitting}
            className="w-full bg-rose-500 text-white py-4 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-rose-400 transition-all disabled:opacity-50"
          >
            {isSubmitting ? 'Initializing...' : 'Initialize Alert'}
          </button>
        </SectionCard>
      </div>
    </div>
  )
}

